INSERT INTO public.academy_courses VALUES (115, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '1. Splash Page', '10. Slicing - Welcome Screen', 'Di bagian ini kita akan belajar slicing atau motongin desain jadi kode. Setiap menu di aplikasi bakal kita pecah dari desain template jadi komponen React Native yang hidup. Jadi nggak cuma liat gambar doang, tapi halaman Splash akan kita ubah menjasi kode.', 'https://drive.google.com/file/d/1ZHxIdZvS3mIgxq3PRoi8y-CYuO4gAdAu/view?usp=drive_link', '0', '2025-08-29 01:36:09', '2025-08-29 01:43:14');
INSERT INTO public.academy_courses VALUES (116, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '2. Get Started Page', '10. Slicing - Welcome Screen', 'Setiap menu di aplikasi bakal kita pecah dari desain template jadi komponen React Native yang hidup. Jadi nggak cuma liat gambar doang, tapi halaman Get Started akan kita ubah menjadi kode.', 'https://drive.google.com/file/d/1ZxFd10MeDYVe54Fip0AZDiVVIzRnnVbZ/view?usp=drive_link', '0', '2025-08-29 01:36:47', '2025-08-29 01:43:34');
INSERT INTO public.academy_courses VALUES (117, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '3. Instalasi Fonts di React Native', '10. Slicing - Welcome Screen', 'Bagaimana agar bisa menggunakan Fonts yang beragam di React Native. Simak tutorial ini dengan baik, kemudian praktekan.', 'https://drive.google.com/file/d/1splD4hSLwZ8a-Guu7nLYWMJt0xv9E444/view?usp=drive_link', '0', '2025-08-29 01:37:41', '2025-08-29 01:41:42');
INSERT INTO public.academy_courses VALUES (118, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '1. Routing di React Native', '11. Navigasi (Routing)', 'Di bagian ini kita bakal belajar routing alias pindah-pindah halaman. Jadi tiap menu yang udah kita slicing, sekarang bisa diklik buat masuk ke halaman lain. Dengan navigasi ini, aplikasi jadi beneran hidup—bisa lompat dari Home ke Profile, dari Task ke Detail, dan balik lagi dengan mulus.', 'https://drive.google.com/file/d/10tleAepOiafCKU1EWfJznEwlNwapXtWK/view?usp=drive_link', '0', '2025-08-29 02:26:18', '2025-08-29 02:40:12');
