INSERT INTO public.academy_courses VALUES (175, 'React Native - My Doctor', 'Informatika', 'Project Aplikasi Mobile Android dengan React Native', 'BWA', '1. Fungsi Logout', '22. Integration - Implementasi Redux', 'Di bagian ini kita bakal belajar state management pakai Redux. Jadi tiap menu yang udah kita slicing dan udah nyambung ke Firebase bakal kita atur alur datanya biar rapi. Dengan Redux, data dari satu menu bisa dipakai di menu lain tanpa ribet. Misalnya user login di awal, datanya bisa langsung kebaca di profile, dashboard, bahkan task list. Semua alur state kita kontrol bareng-bareng supaya aplikasi lebih teratur dan gampang dikembangkan', 'https://drive.google.com/file/d/12QkyIEAD4-31ktH1TP2m_ZTlPrXIhlsm/view?usp=drive_link', '0', '2025-08-29 03:57:01', '2025-08-29 03:59:00');
